function Box(size) {
  this.size = size;
  if (size > 10) {
    return { size: 10 };
  }
  return "small";
}

const a = new Box(3);
const b = new Box(30);

console.log(a.size, b.size);
console.log(typeof a);
console.log(Object.getPrototypeOf(a) === Box.prototype, Object.getPrototypeOf(b) === Box.prototype);
